OUT=Path(__file__).resolve().parent; NOW=datetime.datetime.now(datetime.timezone.utc).isoformat();sources=[]
def add(i,u,pub,section,passage,pop,limit,path):
 p=Path(path);sources.append(dict(id=i,url=u,publisher=pub,section=section,passage=passage,passage_type='faithful_paraphrase',population=pop,limits=limit,limitations=limit,read_at=NOW,reader='astra_nephrologie',cache_path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),reading_scope='selected_sections_actually_read'))
C='/tmp/medina-n02-source-cache/';H='https://www.hug.ch/sites/interhug/files/2024-10/strategie_microhematurie_doi.pdf';A='https://www.erknet.org/fileadmin/Guidelines/Torra_et_al.__2025__Diagnosis__management_and_treatment_of_the_Alport_syndrome.pdf';K='https://kdigo.org/wp-content/uploads/2026/04/KDIGO-2025-IgAN-IgAV-Guideline.pdf'
add('CH-HUG-DEF',H,'HUG, stratégie microhématurie 2024','pp.1–4 ; p.2 algorithme réellement visualisé','Une bandelette positive se confirme par quantification et morphologie. Le laboratoire HUG emploie un seuil de26 M/L ; plus de60% de GR dysmorphiques ou plus de5% d’acanthocytes et/ou cylindres hématiques orientent vers le glomérule. Les seuils et la qualité du prélèvement dépendent de la méthode.','Premier recours suisse, adulte','La conversion d’environ5 M/L par GR/champ est locale et approximative ; ne pas la rendre universelle. Le pourcentage de dysmorphie2017 n’est pas repris. Prévalence jusqu’à un tiers variable, pas incidence suisse deN02.',C+'HUG2024.pdf')
add('CH-HUG-ORIENT',H,'HUG, stratégie2024','§4.1 pp.4–6, algorithme p.2','Toute hématurie glomérulaire confirmée appelle un premier avis néphrologique. Albuminurie, hypertension, baisse de filtration ou signes systémiques accélèrent l’évaluation ; une hématurie isolée exige aussi un suivi. Sans diagnostic néphrologique établi et si elle persiste, une cause urologique reste à rechercher.','Adultes','Urgence d’orientation à proportionner à la trajectoire et aux signes de gravité ; pas ambulance automatique sur albuminurie isolée. Schéma de confirmation à plus d’une semaine seulement en situation stable.',C+'HUG2024.pdf')
add('CH-HUG-URO',H,'HUG, stratégie2024','§4.2 pp.6–9','Une cause traitable ou une anticoagulation ne dispense pas du bilan et du contrôle après résolution. Risque néoplasique et persistance orientent cystoscopie et imagerie. Après bilan négatif, contrôle urinaire dans12mois, ou6mois si faible risque évalué par échographie seule ; nouveaux signes imposent réévaluation.','Adultes, surtout hématurie non glomérulaire','Stratification HUG2024 dérivée notamment d’une recommandation étrangère2020 ; ne pas présenter comme algorithme universel2026 ni l’appliquer à l’enfant. Ne pas recopier l’erreur du tableau5 qui range pacemaker/corps métallique parmi contre-indicationsCT ; IRM/contrastes évalués individuellement.',C+'HUG2024.pdf')
add('EU-HEMAT', 'https://manuel.cuen.fr/wp-content/uploads/2025/10/CUEN-12e-ed-Chap7-hematurie.pdf','CUEN,12e édition2025','pp.118–123, texte hors arbre p122 mal extrait','Urine rouge et hématurie ne sont pas synonymes. Hématies, dysmorphie, cylindres, protéines et contexte orientent ; caillots et temporalité mictionnelle suggèrent une source urologique. L’intensité visible n’est pas une mesure de gravité. Une protéinurie se réévalue sur urine claire.','Adultes et enfants','Le seuil français10hématies/µL diffère du seuilHUG ; unités et méthode précisées. Les formulations systématiques d’imagerie ne remplacent pas stratification suisse ni approche pédiatrique. Le passage porphyrie/activité hème n’est pas repris.', '/tmp/medina-n00-source-cache/FR-HEMATURIA.raw')
add('EU-ALPORT-GEN',A,'ERKNet/ERA/ESPN, guideline2024, publication2025','Introduction,Q1–2,Q4–9, pp.2–5','Les variants COL4A3/4/5 donnent des phénotypes variables ; absence de surdité ou de cas familiaux ne les exclut pas. Génétique des trois gènes à discuter devant hématurie glomérulaire persistante, famille, signes auditifs/oculaires ou histologie compatible. Un variant hétérozygote fréquent peut coexister avec une autre maladie ; panel négatif non exclusif.','Spectre Alport, adultes et enfants','Ne pas appeler bénigne l’hématurie familiale ; variant de signification incertaine non diagnostic. Conseil génétique, pénétrance, phase et limites techniques essentiels ; deux prélèvements en6–12mois sont une définition de cette recommandation et non délai d’attente si signes d’alarme.',C+'ERKNET2024.pdf')
add('EU-ALPORT-RISK',A,'ERKNet/ERA/ESPN2024','Q10–12 et16, pp.5–8','Risque dépend du gène, sexe, mode de transmission, albuminurie et traitement. Les séries familiales recrutées à l’hôpital surestiment le risque de population des hétérozygotesCOL4A3/4. Une biopsie peut rechercher une maladie surajoutée si évolution inattendue ; elle n’est pas nécessaire pour confirmer un diagnostic génétique lié àX ou récessif déjà établi.','Spectre Alport','Pas de pronostic individuel déduit d’un seul pourcentage de cohorte ; données historiques souvent non traitées.',C+'ERKNET2024.pdf')
add('EU-ALPORT-TX',A,'ERKNet/ERA/ESPN2024','Q17–18, pp.8–10','Blocage rénine–angiotensine précoce, particulièrement étudié avec ramipril. Il commence à l’albuminurie dans tous les groupes ; dès hématurie après2ans chez garçons liés àX et formes récessives, mais pas sur seule hématurie isolée chez femmes liées àX ou hétérozygotes autosomiques. SGLT2 à envisager chez adulte albuminurique avec maladie chronique malgré blocage ; preuves pédiatriques insuffisantes.','Alport selon génotype et âge','Recommandation européenne distincte deFI suisse. Ramipril pédiatrique hors indication : initiation1–2mg/m²/j, plafond6 selon expertise ; pas transposition au schémaFI adulte. SGLT2 : avis expert, essais précoces limités.',C+'ERKNET2024.pdf')
add('EU-ALPORT-SUIVI',A,'ERKNet/ERA/ESPN2024','Q12–14,Q19–20, pp.6–7,10–11','Suivi adapté : hétérozygoteCOL4A3/4 adulte asymptomatique urines tous1–2ans et pression annuelle ; après albuminurie et traitement, fonction/albuminurie tous6–12mois. Audition et œil selon mode de transmission. Don familial génétiquement atteint seulement dernier recours spécialisé ; pas de banalisation.','Alport, apparentés et projets familiaux','Intervalles d’experts, modifiés par anomalies, âge et traitement ; ne pas appliquer ce calendrier à touteN02.',C+'ERKNET2024.pdf')
add('EU-YOUNG','https://pmc.ncbi.nlm.nih.gov/articles/PMC13141067/','Latta et al., recommandation allemande, Kidney Int Rep2026;11:106495','Résumé, tableaux3–6 et sections diagnostic primaire/imagerie/génétique','Chez enfant/jeune adulte stable,3–5 contrôles sur3–6mois établissent la persistance ; protéinurie, hypertension ou fonction altérée imposent avis rapide. Échographie d’abord ; cystoscopie non routinière. Acanthocytes évalués manuellement, albuminurie quantifiée ; génétique avant biopsie chez enfant sans autres anomalies.','Enfants et jeunes adultes','Recommandation allemande2026, revue jusqu’à janvier2023 ; l’archive américaine est hébergeur, pas une recommandation américaine. Extraits fournis parParallel et texteXML disponible ; pas de prévalence transposée à la Suisse. Figure1 exclue de réutilisation carCCBY-NC-ND.',C+'GERMAN2026-provider.txt')
add('INT-IGA-DX',K,'KDIGO, consensus international2025','§1.2–1.3, pp.S15–S17 etS32–S33','IgAN exige une biopsie ; ni IgA sanguines ni hématurie après infection ne suffisent. Considérer biopsie adulte si protéinurie≥0,5g/j avec suspicion. Chercher causes secondaires et coterMEST-C. Outil pronostique validé sur population biopsiée pour risque de baisse50%DFG ou défaillance jusqu’à7ans ; pas outil de choix thérapeutique.','IgAN primitive, populations des outils','Consulté après Suisse/Europe. PDF direct406 ; texte officiel extrait parParallel, empreinte de texte ; ≥/≤ corrompus parOCR explicitement normalisés selon contexte et source parallèle. Aucune lecture intégrale des71pages revendiquée.',C+'KDIGO-IGA2025-provider.txt')
add('INT-IGA-TX',K,'KDIGO2025','§1.4 recommandations1.4.3.1–2 et1.4.4.1–3, pp.S18–S25','Risque dès protéinurie≥0,5g/j ; objectif<0,5 idéalement<0,3. Réduire les mécanismes immuns et les conséquences de perte néphronique. IEC ouARA à dose tolérée ; sparsentan remplace ce blocage, ne s’ajoute pas. Budésonide ciblé9mois, SGLT2 et autres options selon risques, preuves et autorisations. Corticoïdes systémiques avec prophylaxie seulement en situations spécialisées.','IgAN à risque de progression','Seuils de recommandation non identiques auxFI suissesFilspari/Kinpeygo. Pas traitement médicamenteux universel d’une bandelette positive ; absence de données sur certaines associations ou populations.',C+'KDIGO-IGA2025-provider.txt')
add('INT-IGA-SPECIAL',K,'KDIGO2025','§1.5 pp.S26–S28','Une IRA peut accompagner une hématurie visibleIgAN et nécessite soins de support ; réévaluer histologiquement si fonction ne s’améliore pas dans2semaines après disparition. Une chute≥50%DFG en≤3mois après exclusion des autres causes définitIgAN rapidement progressive ; croissants seuls ne suffisent pas. Grossesse et enfant exigent stratégies propres.','IgAN, situations particulières','Le délai2semaines ne retarde pas une biopsie urgente ni le traitement d’une complication. Pas protocole adulte immunosuppresseur transposé à l’enfant ; nouveaux traitements à discuter avant conception.',C+'KDIGO-IGA2025-provider.txt')
fi=[('RAMIPRIL','7680581590171','Ramipril Zentiva, décembre2021','Néphropathie glomérulaire protéinurie>3g/j :1,25mg/j puis doublement toutes2–3semaines, maximum5mg/j dans cette indication. HTA :2,5mg/j puis jusqu’à10mg/j. Hépatique plafond2,5 ; clairance20–50 initial1,25/plafond5. Grossesse contre-indiquée, délai36h sacubitril/valsartan, surveillance potassium/créatinine et hypotension.','LaFI exacte ne donne pas une indication générale Alport préalbuminurique/IgAN faible protéinurie ; ramipril pédiatriqueAlport hors indication. Ne pas confondre plafond néphropathie5 et HTA10.'),('FILSPARI','7680692410016','Filspari,sparsentan,juin2026','IgAN primitive adulte, protéinurie≥1g/j ouPCR≥0,75g/g.200mg/j14jours puis400si toléré. Pas initiationK>5,5 ; prudencehypotension/œdèmes ; DFG<30non recommandé. Foie avant puis tous3mois, pas initiationASAT/ALAT>2LSN ; ChildCnon recommandé. Grossessecontre-indiquée, contraception jusqu’à1mois après arrêt ; allaitementnon.','FI distingue ARA/antagonistesendothéline/inhibiteursrénine contre-indiqués et IEC prudence ; conduiteKDIGO retenue sans cumulIEC/ARA. Ne pas utiliser ancienne surveillance mensuelle sans l’attribuer. Nourriture indifférente.'),('KINPEYGO','7680692050014','Kinpeygo,budésonide4mg libération modifiée,juin2026','IgAN primitive adulte protéinurie≥1g/j ouPCR≥0,8g/g.16mg matin≥1h avant repas9mois ; arrêtprogressif8mg2semaines, éventuellement4mg2semaines ; nouveaucycle possible selon médecin. Avalerentier. ChildCcontre-indiqué, ChildBsurveiller ; effets systémiques/infections/axeHHS malgré libérationciblée. InhibiteursCYP3A4/pamplemousse àéviter.','Formulation exacte non interchangeable avec budésonide digestif/inhalé ; ni absence de toxicité systémique ni emploi pédiatrique validé. Grossesse àéviter sauf nécessité clinique ; allaitementdécision bénéfice-risque.')]
for n,g,title,para,lim in fi:add('FI-'+n,'https://amiko.oddb.org/fr/fi?gtin='+g,'Information professionnelle suisse viaAmiKo : '+title,'Indications,posologie,organes,contre-indications,mises en garde,interactions,grossesse ; lecture ciblée',para,'Produit exact, adultes sauf mention spécialisée',lim,C+'FI-'+n+'.raw')
add('FI-COSAAR','https://amiko.oddb.org/fr/fi?gtin=7680529040720','FI suisseCosaar, avril2025','Indications,posologie,organes,contre-indications,interactions,grossesse','Losartan HTA50mg/j puis100 ; hypovolémie envisager25. Indication rénaleFI : diabète2 hypertendu avecACR≥300mg/g. Pas adaptation systématique rénale, mais prudence sévère/hypovolémie ; hépatique réduire, sévèrecontre-indiqué. Pas double blocage ; risquesK,lithium,AINS,angio-œdème ; arrêter si grossesse.','Adultes','IgAN/Alport hors indication rénale spécifique de cetteFI ; aucune dose pédiatriqueFI. Cache réutilisé et reformaté pour lecture, original inchangé.','/tmp/medina-n04-source-cache/FI_cosaar.raw')
add('FI-FORXIGA','https://amiko.oddb.org/fr/fi?gtin=7680651760015','FI suisseForxiga,août2026','IndicationMRC,posologie rénale/hépatique,mises en garde,interactions,grossesse','MRC adulte10mg/j avec blocageSRAA maximal toléré ; ne pas initierDFG<25 mais poursuite possible, arrêtavantdialyse/greffe. Hépatique sévère début5 puis10si toléré. Arrêt≥3jours avant chirurgie lourde/jeûne prolongé. Déplétion,acidocétose parfois glycémie peuélevée,infectionsgénitales ; grossessearrêt/allaitementnon.','MRC adulte','Pas expérience non diabétique sansalbuminurie ; traitement non recommandé néphropathie sousimmunosuppresseur dansFI consultée. Ne pas assimiler diabète et indication rénale ni combiner automatiquement les nouveaux traitements.','/tmp/medina-n04-source-cache/FI_forxiga.raw')
for idn,sect,path in [('NORMAL-FILTRE','25-4-microscopic-anatomy-of-the-kidney','/tmp/medina-n04-source-cache/OPENSTAX25_4.raw'),('NORMAL-REIN','25-3-gross-anatomy-of-the-kidney','/tmp/medina-n29-source-cache/OPENSTAX25_3.raw')]:add(idn,'https://openstax.org/books/anatomy-and-physiology-2e/pages/'+sect,'OpenStax,Anatomy andPhysiology2e','Corpuscule,barrière,tubules ; cortex,médulla,voieexcrétrice selon section','Filtration,réabsorption etsécrétion sont distinctes. Barrière endothélium-membrane basale-podocytes retient lescellules ; tubules modifient lefiltrat, voiesexcrétrices conduisent l’urine.','Anatomie/physiologie normale','Texte paraphrasé ; aucune figure actuelleNC utilisée. Images historiques2013 sousCCBY3 vérifiées séparément. Pas reprise des simplifications osmolarité/macula densa.',path)
add('CH-CIM','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686264/master','OFS,CIM-10-GM2024FR','XML :N02,N00–N08,modificateurS14N00_4 .0–.9','N02 classe hématurie récidivante/persistante dans lesglomérulopathies ; exclutR31 etN39.81. Morphologie .0–.8 exige normalement biopsie/autopsie. Le terme historique bénigne de soninclusion ne garantit pas pronosticbénin.','Codage clinique suisse','CIM n’est pas protocole ni correspondance fédérale officielle ; codeétiologique àdocumenter, pas codeAlport ouIgA arbitraire.','/tmp/medina-n04-source-cache/CIM.raw')
add('CH-PROFILES','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','CIMS,PROFILES2017','pp.29,32 :SSP64,159,161,164,173','Hématurie, histologie/génétique, fonction rénale, sédiment et protéinurie sont des situations pédagogiques pertinentes.','Formation médicale suisse','Correspondances pédagogiques, pas banque officielle ; numérotation2017 différente2023.','/workspace/medina-source-cache/C85/profiles2017-official.pdf')
add('CH-MEBEKO','https://www.bag.admin.ch/dam/fr/sd-web/fL9EvX0YPT2d/20260204_Exigences%20MED%202026_f.pdf','MEBEKO,3mars2026','Introduction et§2.1','Examen2026 associe connaissances écrites et compétences cliniques, organisé selon blueprint multidimensionnel fondé surPROFILES.','Examen fédéral2026','ExercicesMEDINA originaux nonofficiels. Empreinte de texte fourni parParallel, pasPDF.','/workspace/medina-source-cache/C85/mebeko2026.md')
